from pathlib import Path
import re

p=Path('cloudflare-lead-relay/src/index.js')
s=p.read_text()
if "TURNSTILE_SITEKEY" in s:
    raise SystemExit('already patched')

s=s.replace("const N8N_IP='167.172.134.50';\n", "const N8N_IP='167.172.134.50';\nconst SITE_HOST='kbuyhouses.com';\nconst TURNSTILE_SITEKEY='0x4AAAAAAFYwOra-KgD5KiWY';\n")
s=s.replace("const json=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});", "const json=(v,s=200,extra={})=>new Response(JSON.stringify(v),{status:s,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...extra}});")
helpers="""function normalizePhone(v){let d=clean(v,60).replace(/\\D/g,'');if(d.length===11&&d.startsWith('1'))d=d.slice(1);return d.length===10?d:'';}\nfunction normalizeAddress(v){return clean(v,500).toLowerCase().replace(/[.,#]/g,' ').replace(/\\b(north carolina|n\\.?c\\.?)\\b/g,' nc ').replace(/\\bstreet\\b/g,' st ').replace(/\\broad\\b/g,' rd ').replace(/\\bavenue\\b/g,' ave ').replace(/\\bdrive\\b/g,' dr ').replace(/\\blane\\b/g,' ln ').replace(/\\bcourt\\b/g,' ct ').replace(/\\bboulevard\\b/g,' blvd ').replace(/\\bparkway\\b/g,' pkwy ').replace(/\\bhighway\\b/g,' hwy ').replace(/\\bnorth\\b/g,' n ').replace(/\\bsouth\\b/g,' s ').replace(/\\beast\\b/g,' e ').replace(/\\bwest\\b/g,' w ').replace(/\\s+/g,' ').trim();}\n"""
s=s.replace('function normalize(r){',helpers+'function normalize(r){',1)
s=re.sub(r"function normalize\(r\)\{.*?return p;\}", "function normalize(r){const p={firstName:clean(r.firstName,120),lastName:clean(r.lastName,120),phone:clean(r.phone,60),email:clean(r.email,320),propertyAddress:clean(r.propertyAddress||r.address,500),sellerSituation:clean(r.sellerSituation||r.situation,500),notes:clean(r.notes,2000),source:clean(r.source||'Website',80),pageUrl:clean(r.pageUrl||'https://kbuyhouses.com/',1000),landingPage:clean(r.landingPage||'/',500),referrer:clean(r.referrer,1000),utmSource:clean(r.utmSource||r.utm_source,300),utmMedium:clean(r.utmMedium||r.utm_medium,300),utmCampaign:clean(r.utmCampaign||r.utm_campaign,500),utmTerm:clean(r.utmTerm||r.utm_term,500),utmContent:clean(r.utmContent||r.utm_content,500),gclid:clean(r.gclid,1000),gbraid:clean(r.gbraid,1000),wbraid:clean(r.wbraid,1000),fbclid:clean(r.fbclid,1000),formStartedAt:clean(r.formStartedAt,100),submittedAt:new Date().toISOString(),submissionId:clean(r.submissionId,150)||crypto.randomUUID(),website:clean(r.website,200),relay:'cloudflare-d1'};p.isTest=r.isTest===true||String(r.isTest||'').toLowerCase()==='true';p.clickId=p.gclid||p.gbraid||p.wbraid||'';const phoneNorm=normalizePhone(p.phone),addressNorm=normalizeAddress(p.propertyAddress);p._contactDedupeKey=phoneNorm&&addressNorm?phoneNorm+'|'+addressNorm:'';if(!p.firstName||!p.phone||!p.propertyAddress)throw new Error('MISSING_REQUIRED_FIELDS');return p;}", s, count=1)
old="function receiptResponse(value,status=200){return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','access-control-allow-origin':SITE_ORIGIN,'vary':'Origin'}});}" 
new="""function receiptResponse(value,status=200){return json(value,status,{'access-control-allow-origin':SITE_ORIGIN,'vary':'Origin'});}\nfunction errorRedirect(p,kind='submission'){try{const u=new URL(p?.pageUrl||HOME);if(u.hostname!==SITE_HOST)return HOME+'?error='+encodeURIComponent(kind);u.searchParams.set('error',kind);u.hash='get-offer';return u.toString();}catch(_e){return HOME+'?error='+encodeURIComponent(kind);}}\nasync function verifyTurnstile(req,raw,env){const token=clean(raw['cf-turnstile-response'],2048);if(!token||!env.TURNSTILE_SECRET)return {ok:false,reason:'missing_turnstile'};try{const body={secret:env.TURNSTILE_SECRET,response:token,idempotency_key:crypto.randomUUID()};const ip=req.headers.get('cf-connecting-ip');if(ip)body.remoteip=ip;const r=await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const v=await r.json();if(v?.success!==true)return {ok:false,reason:'turnstile_failed',codes:v?.['error-codes']||[]};if(v.hostname&&v.hostname!==SITE_HOST)return {ok:false,reason:'hostname_mismatch'};return {ok:true};}catch(_e){return {ok:false,reason:'turnstile_unavailable'};}}\nasync function findSemanticDuplicate(env,p){const now=Date.now();if(p.clickId){const cutoff=new Date(now-24*60*60*1000).toISOString();const row=await env.DB.prepare(\"SELECT id,submission_id,status FROM leads WHERE click_id=? AND created_at>=? AND status NOT IN ('duplicate','rejected','failed') ORDER BY id DESC LIMIT 1\").bind(p.clickId,cutoff).first();if(row)return {...row,reason:'same_click_id_24h'};}if(p._contactDedupeKey){const cutoff=new Date(now-60*60*1000).toISOString();const row=await env.DB.prepare(\"SELECT id,submission_id,status FROM leads WHERE contact_dedupe_key=? AND created_at>=? AND status NOT IN ('duplicate','rejected','failed') ORDER BY id DESC LIMIT 1\").bind(p._contactDedupeKey,cutoff).first();if(row)return {...row,reason:'same_phone_address_60m'};}return null;}"""
s=s.replace(old,new,1)
s=s.replace("if(req.method==='GET'&&u.pathname==='/health'){const c=await env.DB.prepare(\"SELECT COUNT(*) c FROM leads WHERE status IN ('pending','processing')\").first(); return json({ok:true,service:'kbuyhouses-lead-relay',queued:Number(c?.c||0)});}", "if(req.method==='GET'&&u.pathname==='/turnstile-config')return receiptResponse({enabled:true,siteKey:TURNSTILE_SITEKEY});\nif(req.method==='GET'&&u.pathname==='/health'){const c=await env.DB.prepare(\"SELECT COUNT(*) c FROM leads WHERE status IN ('pending','processing')\").first();const d=await env.DB.prepare(\"SELECT COUNT(*) c FROM leads WHERE status='duplicate' AND created_at>=?\").bind(new Date(Date.now()-24*60*60*1000).toISOString()).first();return json({ok:true,service:'kbuyhouses-lead-relay',queued:Number(c?.c||0),duplicates24h:Number(d?.c||0),turnstile:true});}",1)
lead="""if(req.method==='POST'&&u.pathname==='/lead'){const raw=await parse(req);const p=normalize(raw);if(p.website)return Response.redirect(THANK_YOU,303);const tv=await verifyTurnstile(req,raw,env);if(!tv.ok){console.log(JSON.stringify({event:'turnstile_reject',reason:tv.reason,codes:tv.codes||[],submissionId:p.submissionId}));return Response.redirect(errorRedirect(p,'verification'),303);}const existing=await env.DB.prepare('SELECT id,status,payload_json FROM leads WHERE submission_id=?').bind(p.submissionId).first();if(existing)return Response.redirect(THANK_YOU,303);const dup=await findSemanticDuplicate(env,p);p._conversionEligible=conversionEligible(p,raw)&&!dup;p._conversionId=crypto.randomUUID();p._conversionReceipt=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');if(dup){p._duplicateOf=dup.submission_id;p._duplicateReason=dup.reason;p._duplicateDetectedAt=new Date().toISOString();await env.DB.prepare('INSERT INTO leads (submission_id,payload_json,status,created_at,attempts,click_id,contact_dedupe_key,duplicate_of) VALUES (?,?,?,?,0,?,?,?)').bind(p.submissionId,JSON.stringify(p),'duplicate',new Date().toISOString(),p.clickId||null,p._contactDedupeKey||null,dup.id).run();console.log(JSON.stringify({event:'semantic_duplicate',submissionId:p.submissionId,duplicateOf:dup.submission_id,reason:dup.reason}));return Response.redirect(THANK_YOU,303);}await env.DB.prepare('INSERT INTO leads (submission_id,payload_json,status,created_at,attempts,click_id,contact_dedupe_key,duplicate_of) VALUES (?,?,?,?,0,?,?,NULL)').bind(p.submissionId,JSON.stringify(p),'pending',new Date().toISOString(),p.clickId||null,p._contactDedupeKey||null).run();const stored=await env.DB.prepare('SELECT payload_json FROM leads WHERE submission_id=?').bind(p.submissionId).first();if(!stored)throw new Error('LEAD_PERSISTENCE_UNCONFIRMED');const saved=JSON.parse(stored.payload_json);const dest=new URL(THANK_YOU);if(env.CONVERSION_RECEIPTS_ENABLED==='true'&&saved._conversionEligible===true&&saved._conversionReceipt===p._conversionReceipt)dest.hash=new URLSearchParams({submission:p.submissionId,receipt:p._conversionReceipt}).toString();return Response.redirect(dest.toString(),303);}\n"""
s=re.sub(r"if\(req\.method==='POST'&&u\.pathname==='\/lead'\)\{.*?\}\nif\(req\.method==='GET'&&u\.pathname==='\/next'\)\{",lead+"if(req.method==='GET'&&u.pathname==='/next'){",s,count=1,flags=re.S)
s=s.replace("const payload=JSON.parse(row.payload_json);delete payload._conversionReceipt;", "const payload=JSON.parse(row.payload_json);delete payload._conversionReceipt;delete payload['cf-turnstile-response'];",1)
required=['TURNSTILE_SITEKEY','verifyTurnstile','findSemanticDuplicate',"u.pathname==='/turnstile-config'","event:'semantic_duplicate'",'contact_dedupe_key']
missing=[x for x in required if x not in s]
if missing: raise SystemExit('patch verification failed: '+','.join(missing))
p.write_text(s)
print('patched',p)
